private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (bb == null || sb == null) {
        return i;
    }
    try {
        if (!bb.hasRemaining()) {
            return i;
        }
        int b1 = bb.get() & 0xFF;
        int codePoint;
        if ((b1 & 0x80) == 0) {
            // 1-byte sequence
            codePoint = b1;
        } else if ((b1 & 0xE0) == 0xC0) {
            // 2-byte sequence
            if (!bb.hasRemaining()) {
                bb.position(bb.position() - 1);
                return i;
            }
            int b2 = bb.get() & 0xFF;
            if ((b2 & 0xC0) != 0x80) {
                bb.position(bb.position() - 1);
                return i;
            }
            codePoint = ((b1 & 0x1F) << 6) | (b2 & 0x3F);
        } else if ((b1 & 0xF0) == 0xE0) {
            // 3-byte sequence
            if (bb.remaining() < 2) {
                bb.position(bb.position() - 1);
                return i;
            }
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
                bb.position(bb.position() - 2);
                return i;
            }
            codePoint = ((b1 & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
        } else if ((b1 & 0xF8) == 0xF0) {
            // 4-byte sequence
            if (bb.remaining() < 3) {
                bb.position(bb.position() - 1);
                return i;
            }
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            int b4 = bb.get() & 0xFF;
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80 || (b4 & 0xC0) != 0x80) {
                bb.position(bb.position() - 3);
                return i;
            }
            codePoint = ((b1 & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F);
        } else {
            // Invalid first byte
            codePoint = 0xFFFD; // Replacement character
        }

        // Append the decoded code point to the StringBuilder
        if (codePoint <= 0xFFFF) {
            sb.append((char) codePoint);
        } else {
            // Encode as surrogate pair
            codePoint -= 0x10000;
            sb.append((char) ((codePoint >> 10) + 0xD800));
            sb.append((char) ((codePoint & 0x3FF) + 0xDC00));
        }
    } catch (Exception e) {
        // In case of any unexpected error, simply return the original index
        return i;
    }
    return i + 1;
}

