@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    if (target == null) {
        throw new IllegalArgumentException("target graph cannot be null");
    }
    if (resultMap == null) {
        throw new IllegalArgumentException("resultMap cannot be null");
    }
    // Partition vertices into left and right sets based on key naming convention
    List<V> left = new ArrayList<>();
    List<V> right = new ArrayList<>();
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        String key = entry.getKey();
        V vertex = entry.getValue();
        if (vertex == null) {
            continue; // skip null vertices
        }
        target.addVertex(vertex);
        if (key != null && key.toLowerCase().contains("left")) {
            left.add(vertex);
        } else if (key != null && key.toLowerCase().contains("right")) {
            right.add(vertex);
        } else {
            // Default to left partition if no explicit hint
            left.add(vertex);
        }
    }
    // Add edges between every vertex in left and every vertex in right
    for (V l : left) {
        for (V r : right) {
            if (!l.equals(r)) {
                target.addEdge(l, r);
            }
        }
    }
}

