public Mappings diffStructure(String tableName, Mappings mappings) {
    try {
        if (mappings == null) {
            return new Mappings();
        }
        // Retrieve the current mappings for the given table. This method is assumed to exist.
        Mappings current = IndexService.getCurrentMappings(tableName);
        if (current == null) {
            return new Mappings();
        }
        Map<String, Object> currentProps = current.getProperties();
        Map<String, Object> historyProps = mappings.getProperties();
        Map<String, Object> diffProps = new LinkedHashMap<>();
        for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
            String field = entry.getKey();
            if ("_source".equals(field)) {
                continue; // skip _source config
            }
            if (!historyProps.containsKey(field)) {
                diffProps.put(field, entry.getValue());
            }
        }
        Mappings diff = new Mappings();
        diff.setProperties(diffProps);
        return diff;
    } catch (Exception e) {
        // Log the exception if a logger is available; otherwise, return an empty mapping.
        return new Mappings();
    }
}

