public void put(LoggingEvent o){
    if (o == null) {
        return;
    }
    try {
        // If the buffer reference is null, silently drop the event
        if (buffer == null) {
            return;
        }
        // If the buffer is full, silently drop the event
        if (size == capacity) {
            return;
        }
        // Place the event into the buffer
        buffer[writeIndex] = o;
        // Advance the write index in a circular fashion
        writeIndex = (writeIndex + 1) % capacity;
        // Increment the current size
        size++;
    } catch (Exception e) {
        // Silently drop the event on any unexpected exception
    }
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (start > end) {
        throw new IllegalArgumentException("Start time must be less than or equal to end time");
    }
    List<TimeRange> ranges = new ArrayList<>();
    if (start == end) {
        return ranges;
    }
    long maxDuration = FETCH_DATA_DURATION;
    if (maxDuration <= 0) {
        ranges.add(new TimeRange(start, end));
        return ranges;
    }
    long current = start;
    while (current < end) {
        long next;
        if (current > Long.MAX_VALUE - maxDuration) {
            next = end;
        } else {
            next = Math.min(current + maxDuration, end);
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

