static long compressTimeBucket(long timeBucket,int dayStep){
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    int year = (int)(timeBucket / 10000);
    int monthDay = (int)(timeBucket % 10000);
    int month = monthDay / 100;
    int day = monthDay % 100;
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (index < 0 || len < 0 || index > str.length() - len) {
        throw new IndexOutOfBoundsException("index: " + index + ", len: " + len + ", str.length: " + str.length());
    }
    int size = 0;
    int i = index;
    int end = index + len;
    while (i < end) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
            i++;
        } else if (ch <= 0x7FF) {
            size += 2;
            i++;
        } else {
            if (Character.isHighSurrogate(ch) && i + 1 < end) {
                char low = str.charAt(i + 1);
                if (Character.isLowSurrogate(low)) {
                    size += 4;
                    i += 2;
                    continue;
                }
            }
            size += 3;
            i++;
        }
    }
    return size;
}

