public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    if(byteLength < 0){
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if(byteOffset < 0){
        throw new IllegalArgumentException("byteOffset must be non-negative");
    }
    if(byteArrayValue != null && byteOffset + byteLength > byteArrayValue.length){
        throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds source array length");
    }
    int requiredSize = byteOffset + byteLength;
    if(requiredSize > (buffer != null ? buffer.length : 0)){
        int newCapacity = Math.max(buffer != null ? buffer.length * 2 : 16, requiredSize);
        buffer = java.util.Arrays.copyOf(buffer, newCapacity);
    }
    if(byteArrayValue == null){
        java.util.Arrays.fill(buffer, byteOffset, byteOffset + byteLength, (byte)0);
    } else {
        java.util.System.arraycopy(byteArrayValue, byteOffset, buffer, byteOffset, byteLength);
    }
    if(requiredSize > size){
        size = requiredSize;
    }
    return this;
}

