public void removeFromTreeEdgeList() {
    // Remove from the first doubly linked list of tree edges
    if (prevTreeEdge != null) {
        prevTreeEdge.nextTreeEdge = nextTreeEdge;
    }
    if (nextTreeEdge != null) {
        nextTreeEdge.prevTreeEdge = prevTreeEdge;
    }

    // Remove from the second doubly linked list of tree edges
    if (prevTreeEdgeSibling != null) {
        prevTreeEdgeSibling.nextTreeEdgeSibling = nextTreeEdgeSibling;
    }
    if (nextTreeEdgeSibling != null) {
        nextTreeEdgeSibling.prevTreeEdgeSibling = prevTreeEdgeSibling;
    }

    // Nullify this edge's own references to avoid dangling pointers
    prevTreeEdge = null;
    nextTreeEdge = null;
    prevTreeEdgeSibling = null;
    nextTreeEdgeSibling = null;
}

public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        return null;
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
    java.util.regex.Matcher matcher = pattern.matcher(value);
    StringBuffer sb = new StringBuffer();
    while (matcher.find()) {
        String varName = matcher.group(1);
        String replacement = props.getProperty(varName);
        if (replacement == null) {
            replacement = "";
        }
        matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(replacement));
    }
    matcher.appendTail(sb);
    return sb.toString();
}

