private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int len = descriptor.length();
    int i = 0;
    // Helper to consume a single type and return the new index
    java.util.function.IntUnaryOperator consume = new java.util.function.IntUnaryOperator() {
        @Override
        public int applyAsInt(int idx) {
            if (idx >= len) {
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            char c = descriptor.charAt(idx);
            if (c == '[') {
                // Skip all '[' characters
                while (idx < len && descriptor.charAt(idx) == '[') {
                    idx++;
                }
                if (idx >= len) {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                // Now at component type
                c = descriptor.charAt(idx);
                if (c == 'L') {
                    int semicolon = descriptor.indexOf(';', idx);
                    if (semicolon == -1) {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    return semicolon + 1;
                } else {
                    // Primitive component
                    return idx + 1;
                }
            } else if (c == 'L') {
                int semicolon = descriptor.indexOf(';', idx);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                return semicolon + 1;
            } else {
                // Primitive type
                return idx + 1;
            }
        }
    };

    if (descriptor.charAt(0) == '(') {
        // Method descriptor: pop argument types
        i = 1;
        while (i < len && descriptor.charAt(i) != ')') {
            i = consume.applyAsInt(i);
            // Pop one abstract type from the stack
            outputFrameStack.pop();
        }
        // Skip ')'
        if (i >= len || descriptor.charAt(i) != ')') {
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }
        i++; // skip ')'
        // Return type is ignored
    } else {
        // Single type descriptor
        i = consume.applyAsInt(i);
        outputFrameStack.pop();
    }
}

