@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character or char
    if (type != Character.class && type != char.class) {
        throw new Exception("Unsupported target type: " + type);
    }
    // Null values are converted to null
    if (value == null) {
        return null;
    }
    // If the value is already a Character, return it directly
    if (value instanceof Character) {
        return value;
    }
    // If the value is a String, it must be a single character
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return Character.valueOf(str.charAt(0));
        } else {
            throw new Exception("Cannot convert String to Character: string length is not 1");
        }
    }
    // If the value is a Number, cast its int value to a char
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        char c = (char) intVal;
        return Character.valueOf(c);
    }
    // For any other type, conversion is not supported
    throw new Exception("Cannot convert value of type " + value.getClass() + " to Character");
}

