public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) return 2;
    int n = desiredCapacity;
    if ((n & 1) == 0) n++; // make odd
    while (true) {
        boolean isPrime = true;
        if (n <= 3) {
            isPrime = true;
        } else {
            if ((n & 1) == 0) {
                isPrime = false;
            } else {
                int r = (int)Math.sqrt(n);
                for (int i = 3; i <= r; i += 2) {
                    if (n % i == 0) {
                        isPrime = false;
                        break;
                    }
                }
            }
        }
        if (isPrime) return n;
        n += 2;
        if (n < 0) return Integer.MAX_VALUE;
    }
}

