final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index");
    }
    int offset = constantPoolEntryIndex;
    byte tag = classFileBuffer[offset];
    if (tag != 1) {
        throw new IllegalArgumentException("Entry at index is not CONSTANT_Utf8");
    }
    if (offset + 3 > classFileBuffer.length) {
        throw new IllegalArgumentException("Truncated constant pool entry");
    }
    int length = ((classFileBuffer[offset + 1] & 0xFF) << 8) | (classFileBuffer[offset + 2] & 0xFF);
    if (offset + 3 + length > classFileBuffer.length) {
        throw new IllegalArgumentException("Truncated constant pool entry data");
    }
    byte[] bytes = new byte[length];
    System.arraycopy(classFileBuffer, offset + 3, bytes, 0, length);
    String result = new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
    if (charBuffer != null && charBuffer.length >= result.length()) {
        result.getChars(0, result.length(), charBuffer, 0);
    }
    return result;
}

