        }
        result *= i;
    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop nodes must not be null");
    }
    // If start is the stop node, immediately return a circulator to stop
    if (start == stop) {
        return new OuterFaceCirculator(stop);
    }

    Node current = start;
    java.util.Set<Node> visited = new java.util.HashSet<>();
    while (!visited.contains(current)) {
        visited.add(current);

        // Check the predicate
        if (predicate != null && predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }

        // If we reached the stop node, return a circulator to it
        if (current == stop) {
            return new OuterFaceCirculator(stop);
        }

        // Move to the next node in the specified direction
        current = current.getNext(dir);
        if (current == null) {
            // No further node to traverse; return stop as a fallback
            return new OuterFaceCirculator(stop);
        }
    }

    // If we exit the loop, we have looped without finding the predicate or stop
    return new OuterFaceCirculator(stop);
}

