protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        throw new IllegalArgumentException("tour must contain at least one edge");
    }
    // Verify all edges belong to the graph
    for (E e : tour) {
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("edge " + e + " is not part of the graph");
        }
    }
    // Build adjacency map
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(tgt, k -> new ArrayList<>()).add(e);
    }
    // Ensure each vertex has degree 2 (tour property)
    for (Map.Entry<V, List<E>> entry : adjacency.entrySet()) {
        if (entry.getValue().size() != 2) {
            throw new IllegalArgumentException("vertex " + entry.getKey() + " does not have degree 2");
        }
    }
    // Start traversal
    V start = adjacency.keySet().iterator().next();
    V current = start;
    Set<E> remaining = new HashSet<>(tour);
    List<E> orderedEdges = new ArrayList<>();
    while (!remaining.isEmpty()) {
        List<E> edgesAtCurrent = adjacency.get(current);
        E nextEdge = null;
        for (E e : edgesAtCurrent) {
            if (remaining.contains(e)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            throw new IllegalArgumentException("cannot find a connecting edge from vertex " + current);
        }
        orderedEdges.add(nextEdge);
        remaining.remove(nextEdge);
        V src = graph.getEdgeSource(nextEdge);
        V tgt = graph.getEdgeTarget(nextEdge);
        current = src.equals(current) ? tgt : src;
    }
    if (!current.equals(start)) {
        throw new IllegalArgumentException("the edges do not form a closed tour");
    }
    double weight = 0.0;
    for (E e : orderedEdges) {
        weight += graph.getEdgeWeight(e);
    }
    return new GraphWalk<>(graph, start, start, orderedEdges, weight);
}

