    String key = name + "#" + descriptor;
    Integer existingIndex = nameAndTypeMap.get(key);
    if (existingIndex != null) {
        return existingIndex;
    }
    // Create a new constant pool entry
    ConstantPoolEntry entry = new ConstantPoolEntry(name, descriptor);
    constantPool.add(entry);
    int index = constantPool.size() - 1;
    nameAndTypeMap.put(key, index);
    return index;
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(input.length());
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char ch = input.charAt(i);
        if (ch != '\\') {
            sb.append(ch);
            continue;
        }
        // Escape sequence
        if (i + 1 >= len) {
            // Trailing backslash, just append it
            sb.append('\\');
            break;
        }
        char next = input.charAt(i + 1);
        switch (next) {
            case 'n':
                sb.append('\n');
                i++;
                break;
            case 't':
                sb.append('\t');
                i++;
                break;
            case 'r':
                sb.append('\r');
                i++;
                break;
            case 'b':
                sb.append('\b');
                i++;
                break;
            case 'f':
                sb.append('\f');
                i++;
                break;
            case 'v':
                sb.append('\u000B'); // vertical tab
                i++;
                break;
            case '\\':
                sb.append('\\');
                i++;
                break;
            case '\"':
                sb.append('\"');
                i++;
                break;
            case '\'':
                sb.append('\'');
                i++;
                break;
            case '0':
                sb.append('\0');
                i++;
                break;
            case 'x':
                // Hex escape \xHH
                if (i + 3 < len) {
                    char h1 = input.charAt(i + 2);
                    char h2 = input.charAt(i + 3);
                    if (isHexDigit(h1) && isHexDigit(h2)) {
                        int val = Integer.parseInt("" + h1 + h2, 16);
                        sb.append((char) val);
                        i += 3;
                        break;
                    }
                }
                // If not valid, treat as literal 'x'
                sb.append('x');
                i++;
                break;
            default:
                // Octal escape \NNN (up to 3 digits 0-7)
                if (next >= '0' && next <= '7') {
                    int j = i + 1;
                    int val = 0;
                    int count = 0;
                    while (j < len && count < 3) {
                        char d = input.charAt(j);
                        if (d >= '0' && d <= '7') {
                            val = val * 8 + (d - '0');
                            j++;
                            count++;
                        } else {
                            break;
                        }
                    }
                    sb.append((char) val);
                    i = j - 1;
                } else {
                    // Unrecognized escape, keep the character
                    sb.append(next);
                    i++;
                }
                break;
        }
    }
    return sb.toString();
}

