    return result;
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Validate input
    if (bucketsByLabel == null || labels == null) {
        return;
    }
    if (bucketsByLabel.isEmpty() || minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        return;
    }
    // If the source bucket is the same as the target (label 0), nothing to do
    if (minLabel == 0) {
        return;
    }
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }
    // Ensure target bucket exists
    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null) {
        target = new HashSet<>();
        bucketsByLabel.set(0, target);
    }
    // Move vertices and update labels
    for (Integer vertex : source) {
        if (vertex != null && vertex >= 0 && vertex < labels.size()) {
            labels.set(vertex, 0);
        }
        target.add(vertex);
    }
    // Clear the source bucket
    source.clear();
}

