private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffix.add(0);
    }
    long total = 0L;
    for (Integer v : bounds) {
        total += (v == null ? 0L : v.longValue());
    }
    long running = 0L;
    for (int i = n - 1; i >= 0; i--) {
        Integer v = bounds.get(i);
        running += (v == null ? 0L : v.longValue());
        suffix.set(i, (int) running);
    }
    return new Pair<>(suffix, total);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("Array is null");
    }
    int len = arr.length;
    if (from < 0 || to >= len) {
        throw new IndexOutOfBoundsException("Index out of bounds: from=" + from + ", to=" + to + ", length=" + len);
    }
    if (from > to) {
        throw new IllegalArgumentException("from index greater than to index: from=" + from + ", to=" + to);
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list == this) {
        return;
    }
    // Lock both lists in a consistent order to avoid deadlock
    Object firstLock = System.identityHashCode(this) < System.identityHashCode(list) ? this : list;
    Object secondLock = firstLock == this ? list : this;
    synchronized (firstLock) {
        synchronized (secondLock) {
            ListNodeImpl<E> node;
            while ((node = list.getFirstNode()) != null) {
                list.removeListNode(node);
                this.addListNode(node);
            }
        }
    }
}

