private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    Object[] arr = vertices.toArray();
    for (int i = 0; i < size; i++) {
        V vi = (V) arr[i];
        if (vi == null) {
            return false;
        }
        for (int j = i + 1; j < size; j++) {
            V vj = (V) arr[j];
            if (vj == null) {
                return false;
            }
            if (!graph.containsEdge(vi, vj)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (keys == null) {
        return result;
    }
    for (K key : keys) {
        if (key == null) {
            result.add(0);
            continue;
        }
        K maxLower = null;
        for (K other : keys) {
            if (other == null) {
                continue;
            }
            @SuppressWarnings("unchecked")
            java.lang.Comparable<? super K> comp = (java.lang.Comparable<? super K>) other;
            if (comp.compareTo(key) <= 0) {
                if (maxLower == null) {
                    maxLower = other;
                } else {
                    @SuppressWarnings("unchecked")
                    java.lang.Comparable<? super K> compMax = (java.lang.Comparable<? super K>) maxLower;
                    if (comp.compareTo(maxLower) > 0) {
                        maxLower = other;
                    }
                }
            }
        }
        if (maxLower != null) {
            if (maxLower instanceof Integer) {
                result.add((Integer) maxLower);
            } else {
                try {
                    result.add(Integer.parseInt(maxLower.toString()));
                } catch (NumberFormatException e) {
                    result.add(0);
                }
            }
        } else {
            result.add(0);
        }
    }
    return result;
}

private void pop(final String descriptor){
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor cannot be null");
    }
    int count = 0;
    int i = 0;
    int len = descriptor.length();
    if (len == 0) {
        throw new IllegalArgumentException("descriptor cannot be empty");
    }
    if (descriptor.charAt(0) == '(') {
        // method descriptor
        i = 1;
        while (i < len && descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            if (c == 'L') {
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
                }
                i = semicolon + 1;
                count++;
            } else if (c == '[') {
                // array type
                while (i < len && descriptor.charAt(i) == '[') {
                    i++;
                }
                if (i >= len) {
                    throw new IllegalArgumentException("Invalid descriptor: incomplete array type");
                }
                if (descriptor.charAt(i) == 'L') {
                    int semicolon = descriptor.indexOf(';', i);
                    if (semicolon == -1) {
                        throw new IllegalArgumentException("Invalid descriptor: missing ';' for array object type");
                    }
                    i = semicolon + 1;
                } else {
                    // primitive
                    i++;
                }
                count++;
            } else {
                // primitive
                i++;
                count++;
            }
        }
        if (i >= len || descriptor.charAt(i) != ')') {
            throw new IllegalArgumentException("Invalid descriptor: missing ')'");
        }
        // return type is ignored
    } else {
        // type descriptor
        char c = descriptor.charAt(0);
        if (c == 'L') {
            int semicolon = descriptor.indexOf(';', 0);
            if (semicolon == -1) {
                throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
            }
            count = 1;
        } else if (c == '[') {
            // array type
            while (i < len && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= len) {
                throw new IllegalArgumentException("Invalid descriptor: incomplete array type");
            }
            if (descriptor.charAt(i) == 'L') {
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: missing ';' for array object type");
                }
                // i = semicolon + 1;
            } else {
                // primitive
                // i++;
            }
            count = 1;
        } else {
            // primitive
            count = 1;
        }
    }
    for (int j = 0; j < count; j++) {
        if (outputFrameStack.isEmpty()) {
            throw new IllegalStateException("Output frame stack underflow while popping descriptor: " + descriptor);
        }
        outputFrameStack.pop();
    }
}

