private List<Integer> computeUpperBounds(List<K> keys) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (keys == null) {
        return result;
    }
    java.util.TreeSet<Integer> sorted = new java.util.TreeSet<>();
    for (K k : keys) {
        if (k == null) {
            continue;
        }
        if (!(k instanceof Integer)) {
            throw new IllegalArgumentException("Key type must be Integer");
        }
        sorted.add((Integer) k);
    }
    for (K k : keys) {
        if (k == null) {
            result.add(Integer.MAX_VALUE);
            continue;
        }
        if (!(k instanceof Integer)) {
            throw new IllegalArgumentException("Key type must be Integer");
        }
        Integer bound = sorted.higher((Integer) k);
        result.add(bound != null ? bound : Integer.MAX_VALUE);
    }
    return result;
}

