public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        return relativePath;
    }
    if (relativePath == null) {
        return path;
    }

    // Preserve whether the original path was absolute
    boolean isAbsolute = path.startsWith("/");

    // Remove trailing slash for consistent splitting (except for root "/")
    if (path.length() > 1 && path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }

    // Split the base path into components
    String[] baseParts = path.split("/");
    java.util.List<String> stack = new java.util.ArrayList<>();
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        stack.add(part);
    }

    // Process the relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        result.append(stack.get(i));
        if (i < stack.size() - 1) {
            result.append("/");
        }
    }

    // Handle the case where the result is empty but the original was absolute
    if (result.length() == 0 && isAbsolute) {
        result.append("/");
    }

    return result.toString();
}

