public int readTag() throws IOException {
    try {
        int result = 0;
        int shift = 0;
        while (shift < 32) {
            int b = readRawByte();
            result |= (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                return result;
            }
            shift += 7;
        }
        throw new IOException("Malformed varint");
    } catch (EOFException e) {
        return 0;
    }
}

